pub fn HSD_CObjRemoveAnim<'a>(ctx: &'a Ctx, cobj: HSD_CObj<'a>) {
    let __frame = ctx.stack_frame(0x18);
    let mut cobj = cobj;
    if Handle::is_null(cobj) {
        return;
    }
    inl_HSD_CObjRemoveAnimByFlags_unfused(ctx, cobj, 0);
}

pub fn HSD_CObjAddAnim<'a>(ctx: &'a Ctx, cobj: HSD_CObj<'a>, canim: HSD_CameraAnim<'a>) {
    let __frame = ctx.stack_frame(0x18);
    let mut cobj = cobj;
    let mut canim = canim;
    if Handle::is_null(cobj) {
        return;
    }
    if Handle::is_null(canim) {
        return;
    }
    if !Handle::is_null((cobj).aobj()) {
        fns::HSD_AObjRemove(ctx, (cobj).aobj());
    }
    (cobj).set_aobj(fns::HSD_AObjLoadDesc(ctx, (canim).aobjdesc()));
    fns::HSD_WObjAddAnim(
        ctx,
        fns::HSD_CObjGetEyePositionWObj(ctx, cobj),
        (canim).eye_anim(),
    );
    fns::HSD_WObjAddAnim(
        ctx,
        fns::HSD_CObjGetInterestWObj(ctx, cobj),
        (canim).interest_anim(),
    );
}

